def group_adjacent_states(grid):
    # Create a dictionary to store the grouped adjacent states
    grouped_states = {}

    # Iterate over each cell in the grid
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            # If this is not the start or goal state, add it to the grouped states dictionary
            if grid[i][j] != "X" and (i, j) != (grid.index({"start": 0}) // len(grid[0]), grid[0].index(0)):
                group = []

                # Check all adjacent cells for a valid movement in the cardinal directions
                for x, y in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    new_i, new_j = i + x, j + y

                    # If the new position is within the grid boundaries and not a wall, add it to the group
                    if 0 <= new_i < len(grid) and 0 <= new_j < len(grid[0]) and grid[new_i][new_j] != "X":
                        group.append(new_i * len(grid[0]) + new_j)

                # Add the group to the grouped states dictionary
                grouped_states[len(grouped_states)] = group

    return list(grouped_states.values())

